 film: f32, // @default 0.22 Thin film edge strength.
};
fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
 var o = surfaceDefaults(s);
 let v = normalize(s.eye - s.world);
 let fresnel = pow(1.0 - abs(dot(normalize(s.normal), v)), 3.0);
 let machiningPhase = s.uv.y * 240.0 + 0.15 * sin(s.uv.x * 45.0);
 let scratches = sin(machiningPhase) * (1.0 - smoothstep(0.6, 2.6, fwidth(machiningPhase)));
 let finePhase = s.uv.x * 2200.0 + sin(s.uv.y * 53.0);
 let fine = sin(finePhase) * (1.0 - smoothstep(0.6, 2.6, fwidth(finePhase)));
 let grain = scratches * 0.7 + fine * 0.3;
 let phase = s.uv.x * 9.0 + fresnel * 5.4;
 let iridescent = 0.5 + 0.5 * cos(vec3f(0.2, 2.3, 4.4) + phase);
 let edge = pow(abs(cos(s.uv.y * 6.283185307)), 7.0);
 o.albedo = vec4f(vec3f(0.22, 0.13, 0.058) * (1.0 + p.striation * grain) + iridescent * p.film * fresnel * edge, 1.0);
 o.roughness = clamp(0.21 + grain * 0.035 - edge * 0.025, 0.16, 0.38);
 o.metallic = 1.0;
 o.emissive = iridescent * fresnel * edge * 0.014;
 return o;
}

