parameters.expressions:
f = mod(phase, 3);
a = smoothstep(0.12, 0.88, f);
b = smoothstep(1.12, 1.88, f);
c = smoothstep(2.12, 2.88, f);
ca = (f < 1) * a + (f >= 1) * (f < 2) * (1 - b);
oa = (f >= 1) * (f < 2) * b + (f >= 2) * (1 - c);
cm = smoothstep(0, 1, form) * (1 - smoothstep(1, 2, form));
om = smoothstep(1, 2, form);
crown = autoForm * ca + (1 - autoForm) * cm;
orbit = autoForm * oa + (1 - autoForm) * om;
